 *  (monthly) that day in every month from the start's month, falling on the month's last day when beyond it,
 *  those before the start and those in one of its pauses left out — the same dates the generate makes. */
export function nextPlanDates(plan: Plan, today: string): string[] {
  const out: string[] = [];
  const start = Date.parse(`${plan.start}T00:00:00Z`);
  const end = Date.parse(`${plan.end}T00:00:00Z`);
  const after = Date.parse(`${today}T00:00:00Z`);
  if (Number.isNaN(start) || Number.isNaN(end) || Number.isNaN(after)) return out;
  if (plan.day == null) {
    const step = (plan.every ?? 0) * DAY_MS;
    if (step <= 0) return out;
    let on = start;
    if (on <= after) on += Math.floor((after - on) / step + 1) * step;
    for (; on <= end && out.length < 5; on += step) if (!skipped(plan, isoDay(on))) out.push(isoDay(on));
    return out;
  }
  const first = new Date(start);
  for (let m = first.getUTCFullYear() * 12 + first.getUTCMonth(); out.length < 5; m++) {
    const y = Math.floor(m / 12);
    const mo = m % 12;
    if (Date.UTC(y, mo, 1) > end) break;
    const last = new Date(Date.UTC(y, mo + 1, 0)).getUTCDate();
    const on = Date.UTC(y, mo, Math.min(plan.day, last));
    if (on >= start && on > after && on <= end && !skipped(plan, isoDay(on))) out.push(isoDay(on));
  }
  return out;
}

/** One plan's row: its figures, next dates and whether it is paused, with buttons that pause and resume it, an
 *  entry that changes its amount from the sheet's today, and its amount changes, oldest first. A refused pause,
 *  resume or change shows an error on the row, gone when the next one is pressed or the entry is changed. */
function PlanRow({ sheetId, plan, today }: { sheetId: string; plan: Plan; today: string | undefined }) {
  const fig = useFigure();
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const toggle = useMutation({
    mutationFn: (action: 'pause' | 'resume') =>
      postJson<{ plans: Plan[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/plans/${plan.id}/${action}`, {}),
    onSuccess: (data) => queryClient.setQueryData(plansKey(sheetId), data.plans),
  });
  const [amount, setAmount] = useState('');
  const change = useMutation({
    mutationFn: (value: string) =>
      postJson<{ plans: Plan[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/plans/${plan.id}/amount`, { amount: value }),
    onSuccess: (data) => {
      setAmount('');
      queryClient.setQueryData(plansKey(sheetId), data.plans);
    },
  });
  const save = () =>
    submitOnce(() => {
      toggle.reset();
      change.reset();
      return change.mutateAsync(amount.trim());
    });
  const press = (action: 'pause' | 'resume') =>
    submitOnce(() => {
      toggle.reset();
      change.reset();
      return toggle.mutateAsync(action);
    });
  return (
    <tr data-testid={`plan-row-${plan.id}`}>
      <td data-testid="plan-amount-shown">{fig(plan.amount)}</td>
      <td data-testid="plan-start">{plan.start}</td>
      <td data-testid="plan-every">{plan.every ?? ''}</td>
      <td data-testid="plan-day">{plan.day ?? ''}</td>
      <td data-testid="plan-end">{plan.end}</td>
      <td data-testid="plan-generated">{plan.generated}</td>
      <td data-testid="plan-next-dates">{today ? nextPlanDates(plan, today).join(', ') : ''}</td>
      <td data-testid="plan-paused">{plan.paused ? 'yes' : 'no'}</td>
      <td>
        <button type="button" data-testid="plan-pause" disabled={toggle.isPending} onClick={() => press('pause')}>
          Pause
        </button>{' '}
        <button type="button" data-testid="plan-resume" disabled={toggle.isPending} onClick={() => press('resume')}>
          Resume
        </button>
        <input
          type="text"
          placeholder="new amount"
          data-testid="plan-amount"
          value={amount}
          onChange={(e) => {
            setAmount(e.target.value);
            change.reset();
          }}
        />{' '}
        <button type="button" data-testid="plan-amount-save" disabled={change.isPending} onClick={save}>
          Save amount
        </button>
        {toggle.isError && <span data-testid="plan-error">{toggle.error.message}</span>}
        {change.isError && <span data-testid="plan-error">{change.error.message}</span>}
      </td>
      <td>
        {(plan.changes ?? []).map((c, i) => (
          <div key={i} data-testid="plan-change-line">
            {c.on} amount={c.amount}
          </div>
        ))}
      </td>
    </tr>
  );
}

/** A person's plans, each with how many claims it has made so far and its next five dates after the sheet's today and whether it is paused, and a form that adds one: an amount, a
 *  start date, every N days (a whole number, at least 1) or a day of the month (1 to 31), and an end date not before the start. A refused plan
 *  shows an error on the row. */
function PersonPlans({ sheetId, personId }: { sheetId: string; personId: number }) {
  const plans = usePlans(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const [amount, setAmount] = useState('');
  const [start, setStart] = useState('');
  const [every, setEvery] = useState('');
  const [day, setDay] = useState('');
  const [end, setEnd] = useState('');

  const add = useMutation({
    mutationFn: (f: { amount: string; start: string; every: string; day: string; end: string }) =>
      postJson<{ plans: Plan[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/plans`, f),
    onSuccess: (data) => {
      setAmount('');
      setStart('');
      setEvery('');
      setDay('');
      setEnd('');
      queryClient.setQueryData(plansKey(sheetId), data.plans);
    },
  });

  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    add.reset();
  };

  const mine = (plans.data ?? []).filter((p) => p.personId === personId);

  return (
    <tr>
      <td colSpan={PERSON_ROW_SPAN}>
        {mine.length > 0 && (
          <table>
            <thead>
              <tr>
                <th>Plan amount</th>
                <th>Start</th>
                <th>Every (days)</th>
                <th>Day of month</th>
                <th>End</th>
                <th>Generated</th>
                <th>Next dates</th>
                <th>Paused</th>
                <th></th>
                <th>Changes</th>
              </tr>
            </thead>
            <tbody>
              {mine.map((p) => (
                <PlanRow key={p.id} sheetId={sheetId} plan={p} today={today} />
              ))}
            </tbody>
          </table>
        )}
        <form
          data-testid="plan-form"
          onSubmit={(e) => {
            e.preventDefault();
            submitOnce(() => {
              add.reset();
              return add.mutateAsync({ amount: amount.trim(), start: start.trim(), every: every.trim(), day: day.trim(), end: end.trim() });
            });
          }}
        >
          Plan:{' '}
          <input type="text" placeholder="amount" data-testid="plan-form-amount" value={amount} onChange={field(setAmount)} />{' '}
          <input type="text" placeholder="start yyyy-mm-dd" data-testid="plan-form-start" value={start} onChange={field(setStart)} />{' '}
          <input type="text" placeholder="every N days" data-testid="plan-form-every" value={every} onChange={field(setEvery)} />{' '}
          <input type="text" placeholder="or day of month 1-31" data-testid="plan-form-day" value={day} onChange={field(setDay)} />{' '}
          <input type="text" placeholder="end yyyy-mm-dd" data-testid="plan-form-end" value={end} onChange={field(setEnd)} />{' '}
          <button type="submit" data-testid="plan-form-submit" disabled={add.isPending}>
            Add plan
          </button>
          {add.isError && <span data-testid="plan-error">{add.error.message}</span>}
        </form>
      </td>
    </tr>
  );
}

/** Generate the plans' claims: a DRAFT claim for every plan date up to its end and the sheet's today that has
 *  none yet. Shows how many were made (gone while it runs). */
function GeneratePlans({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const generate = useMutation({
    mutationFn: () => postJson<{ made: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/plan-generate`, {}),
    // The new claims are re-read before the count shows, so a count on screen means its rows are there too.
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: plansKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });
  return (
    <section>
      <button
        type="button"
        data-testid="plan-generate"
        disabled={generate.isPending}
        onClick={() =>
          submitOnce(() => {
            generate.reset();
            return generate.mutateAsync();
          })
        }
      >
        Generate plan claims
      </button>
      {generate.isSuccess && (
        <>
          {' '}
          Made <strong data-testid="plan-generated-count">{generate.data.made}</strong>
        </>
      )}
      {generate.isError && <p data-testid="plan-generate-error">{generate.error.message}</p>}
    </section>
  );
}

export const contributions = [
  PersonDetail.fill({ order: 20, Component: PersonPlans }),
  SheetBody.fill({ order: 18, Component: ({ sheetId }) => <GeneratePlans sheetId={sheetId} /> }),
];

